using System.Web.Mvc;using FindIt.DAL;namespace FindIt.Controllers{public class StudentController:Controller{ItemRepository items=new ItemRepository();private int U{get{return Session["UserId"]==null?0:(int)Session["UserId"];}}protected override void OnActionExecuting(System.Web.Mvc.ActionExecutingContext c){if(U==0||Session["Role"] as string!="Student")c.Result=RedirectToAction("Login","Account");base.OnActionExecuting(c);}public ActionResult Dashboard(){return View(items.Stats(U));}public ActionResult MyReports(){return View(items.Search("","","","",null).FindAll(x=>x.UserId==U));}}}